import React, { forwardRef, type ReactNode } from 'react'
import { sv, useTheme, useVariants, withAlpha, type Style, type Theme, type VariantProps } from '@gpuix-ui/core'
import type { DivProps, Instance } from '@gpuix-ui/primitives'
import { asText } from './internal'

export const badgeVariants = (t: Theme) =>
  sv({
    base: {
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      gap: 4,
      height: 22,
      paddingLeft: 8,
      paddingRight: 8,
      borderRadius: t.radius.full,
      borderWidth: 1,
      borderColor: '#00000000',
      flexShrink: 0,
    },
    variants: {
      variant: {
        default: { backgroundColor: t.colors.primary },
        secondary: { backgroundColor: t.colors.secondary },
        outline: { borderColor: t.colors.border },
        destructive: { backgroundColor: t.appearance === 'dark' ? withAlpha(t.colors.destructive, 0.6) : t.colors.destructive },
        success: { backgroundColor: withAlpha(t.colors.success, 0.18), borderColor: withAlpha(t.colors.success, 0.4) },
      },
    },
    defaultVariants: { variant: 'default' },
  })

export interface BadgeProps extends Omit<DivProps, 'style' | 'children'>, VariantProps<ReturnType<typeof badgeVariants>> {
  style?: Style
  children?: ReactNode
}

export const Badge = forwardRef<Instance, BadgeProps>(function Badge({ variant = 'default', style, children, ...props }, ref) {
  const t = useTheme()
  const variants = useVariants(badgeVariants)
  const color =
    variant === 'default'
      ? t.colors.primaryForeground
      : variant === 'destructive'
        ? t.colors.destructiveForeground
        : variant === 'success'
          ? t.colors.success
          : t.colors.foreground
  return (
    <div {...props} ref={ref} style={variants({ variant, style })}>
      {asText(children, { fontFamily: t.font.sans, fontSize: t.font.size.xs, lineHeight: t.font.lineHeight.xs, fontWeight: 500, color, whiteSpace: 'nowrap' })}
    </div>
  )
})

/** Helpers shared by the styled components. */
import React, { useState, type ReactNode } from 'react'
import type { EventPayload } from '@gpuix/react'
import type { Style } from '@gpuix-ui/core'

/**
 * GPUI does not inherit `color`, so a bare string child would paint black.
 * Wrap string and number children in a `<text>` carrying the given style;
 * pass elements through untouched.
 */
export function asText(children: ReactNode, style: Style): ReactNode {
  if (children == null || typeof children === 'boolean') return null
  if (typeof children === 'string' || typeof children === 'number') return <text style={style}>{String(children)}</text>
  if (Array.isArray(children)) {
    if (children.every((child) => typeof child === 'string' || typeof child === 'number')) return <text style={style}>{children.join('')}</text>
    // Mixed children, like an icon next to a label: wrap just the strings.
    return children.map((child, index) =>
      typeof child === 'string' || typeof child === 'number' ? (
        <text key={`text-${index}`} style={style}>
          {String(child)}
        </text>
      ) : (
        child
      ),
    )
  }
  return children
}

/** Track native focus on an element, for a focus ring. */
export function useFocusState(handlers: { onFocus?: (event: EventPayload) => void; onBlur?: (event: EventPayload) => void } = {}) {
  const [focused, setFocused] = useState(false)
  return {
    focused,
    onFocus: (event: EventPayload) => {
      handlers.onFocus?.(event)
      setFocused(true)
    },
    onBlur: (event: EventPayload) => {
      handlers.onBlur?.(event)
      setFocused(false)
    },
  }
}

/** Track hover in React state, for components that render different children on hover. */
export function useHoverState() {
  const [hovered, setHovered] = useState(false)
  return { hovered, onMouseEnter: () => setHovered(true), onMouseLeave: () => setHovered(false) }
}
